import { base44 } from "@/api/base44Client";
import { ensureReusableRecord } from "@/components/estimator/products/reusableSaveIdempotency";
import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

// Generic module-keyed template persistence on the shared ProjectTemplate
// entity. Mirrors foundationTemplateService exactly so every estimator module
// gets identical idempotent save/list/delete semantics without duplicating the
// recovery logic per module (#79).
export async function saveModuleTemplate({ moduleKey, idempotencyKey, data, label = "Module template" }) {
  return ensureReusableRecord({
    entity: base44.entities.ProjectTemplate,
    idempotencyKey,
    data: { ...data, module_key: moduleKey },
    label,
  });
}

export async function listModuleTemplates({ moduleKey }) {
  return loadAllEntityRows({
    entity: base44.entities.ProjectTemplate,
    query: { module_key: moduleKey },
    sort: "created_date",
    label: "Module templates",
  });
}

// Mirrors the canonical not-found detection in builderEntityPersistence
// (isEntityNotFoundError): a genuinely-missing record is "already gone" while
// every other fetch failure stays an error so the UI never drops a live row.
// All message fields are scanned (not just the first) so a generic top-level
// message cannot hide a nested "not found" detail.
const isNotFound = (e) => {
  const status = Number(e?.status || e?.response?.status || e?.response?.statusCode || e?.data?.status || 0);
  if (status === 404) return true;
  const message = [
    e?.message,
    e?.response?.data?.message,
    e?.response?.data?.error,
    e?.data?.message,
    e?.data?.error,
  ].map((v) => String(v || "").toLowerCase()).join(" ");
  return message.includes("not found") || message.includes("does not exist");
};

export async function deleteModuleTemplate(templateId, label = "Module template") {
  const id = String(templateId || "").trim();
  if (!id) throw new Error(`${label} id is required.`);

  let current;
  try {
    current = await base44.entities.ProjectTemplate.get(id);
  } catch (e) {
    // Only a definitive not-found is "already gone" — a transient read error
    // (500/429/timeout) must NOT mint a false delete-success; rethrow so the
    // dialog surfaces the failure instead of dropping a live row.
    if (isNotFound(e)) return true;
    throw e;
  }
  if (current === null || current === undefined || typeof current !== "object" || Array.isArray(current) || current.id !== id) {
    throw new Error(`${label} record could not be verified; delete aborted.`);
  }
  await deleteEntityIfUnchanged({
    entity: base44.entities.ProjectTemplate,
    record: current,
    label,
  });
  return true;
}

import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Trash2 } from "lucide-react";
import { deleteModuleTemplate, listModuleTemplates, saveModuleTemplate } from "./moduleTemplateService";

// Generic save/load/delete template dialog keyed by module (#79). The caller
// supplies how the live project state becomes a template payload
// (buildTemplateData) and how a row is described in the list (describeTemplate);
// the dialog owns the idempotent-save retry key exactly like the Foundation
// implementation it is generalized from.
export default function ModuleTemplateDialog({
  open,
  mode,
  onClose,
  project,
  onApply,
  moduleKey,
  title = "Module",
  buildTemplateData,
  describeTemplate,
}) {
  const [templates, setTemplates] = useState([]);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [error, setError] = useState(null);
  const saveAttemptRef = useRef({ signature: "", key: "" });
  const loadSeqRef = useRef(0);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const loadRows = () => {
    const seq = ++loadSeqRef.current;
    setLoading(true);
    setLoadFailed(false);
    setError(null);
    // loadAllEntityRows rethrows failures — an un-caught rejection would both
    // leak an unhandled promise and render a fake "no templates" list. The
    // catch marks the load failed and offers a retry (same honest-empty shape
    // the landed O-014 Foundation dialog uses).
    listModuleTemplates({ moduleKey })
      .then((rows) => {
        if (!mountedRef.current || loadSeqRef.current !== seq) return;
        setTemplates(rows || []);
        setError(null);
      })
      .catch((e) => {
        if (!mountedRef.current || loadSeqRef.current !== seq) return;
        setTemplates([]);
        setLoadFailed(true);
        setError(e?.message || "Templates could not be loaded.");
      })
      .finally(() => {
        if (mountedRef.current && loadSeqRef.current === seq) setLoading(false);
      });
  };

  useEffect(() => {
    if (!open) return;
    saveAttemptRef.current = { signature: "", key: "" };
    setTemplates([]);
    setError(null);
    setLoadFailed(false);
    if (mode !== "load") return;
    loadRows();
  }, [open, mode, moduleKey]);

  const save = async () => {
    if (!name.trim()) return;
    setBusy(true);
    try {
      const data = {
        template_name: name.trim(),
        module_key: moduleKey,
        project_data: buildTemplateData ? buildTemplateData(project) : project,
      };
      const signature = JSON.stringify(data);
      if (saveAttemptRef.current.signature !== signature) {
        saveAttemptRef.current = {
          signature,
          key: `${moduleKey}_template_save:${crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`}`,
        };
      }
      await saveModuleTemplate({
        moduleKey,
        idempotencyKey: saveAttemptRef.current.key,
        data,
        label: `${title} template`,
      });
      setName("");
      saveAttemptRef.current = { signature: "", key: "" };
      setError(null);
      onClose();
    } catch (e) {
      // The dialog stays open and honest — a swallowed rejection here meant a
      // silent save failure with no visible state anywhere.
      setError(e?.message || "Template could not be saved.");
    } finally {
      setBusy(false);
    }
  };

  const remove = async (t) => {
    if (!window.confirm(`Delete template "${t.template_name || "Untitled"}"?`)) return;
    try {
      await deleteModuleTemplate(t.id, `${title} template`);
      setTemplates((prev) => prev.filter((x) => x.id !== t.id));
      setError(null);
    } catch (e) {
      // The row honestly stays in the list — and the failure is now visible
      // instead of an empty-catch no-op.
      setError(e?.message || "Template could not be deleted.");
    }
  };

  const apply = (t) => {
    try {
      onApply(t.project_data || {});
      setError(null);
      onClose();
    } catch (e) {
      setError(e?.message || "Template could not be applied.");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle className="text-[15px]">
            {mode === "save" ? "Save as Template" : `${title} Templates`}
          </DialogTitle>
        </DialogHeader>

        {error ? (
          <div role="alert" className="text-[12px] text-red-700 bg-red-50 border border-red-200 rounded px-2 py-1.5">
            {error}
          </div>
        ) : null}

        {mode === "save" ? (
          <div className="space-y-3">
            <label className="text-[11px] text-gray-500 block">
              Template name
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder={`e.g. Standard ${title} setup`}
                className="w-full h-[30px] px-2 border border-gray-300 rounded-sm text-[12px] focus:outline-none focus:border-red-400"
              />
            </label>
            <div className="flex justify-end gap-2">
              <button type="button" onClick={onClose} className="h-[30px] px-3 border border-gray-300 rounded-sm text-[12px]">
                Cancel
              </button>
              <button
                type="button"
                onClick={save}
                disabled={busy}
                className="h-[30px] px-4 rounded-sm bg-lime-300 border border-lime-400 text-[12px] font-bold text-gray-800 disabled:opacity-60"
              >
                Save Template
              </button>
            </div>
          </div>
        ) : loading ? (
          <p className="text-[12px] text-gray-500 py-4">Loading…</p>
        ) : loadFailed ? (
          <div className="py-4 space-y-2">
            <p className="text-[12px] text-gray-500">Templates could not be loaded.</p>
            <button
              type="button"
              onClick={loadRows}
              className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
            >
              Retry
            </button>
          </div>
        ) : templates.length === 0 ? (
          <p className="text-[12px] text-gray-500 py-4">No {title.toLowerCase()} templates saved yet.</p>
        ) : (
          <div className="divide-y divide-gray-200 max-h-[320px] overflow-y-auto">
            {templates.map((t) => (
              <div key={t.id} className="flex items-center gap-2 py-2">
                <div className="flex-1">
                  <div className="text-[12px] font-semibold text-gray-800">{t.template_name}</div>
                  <div className="text-[11px] text-gray-500">
                    {describeTemplate ? describeTemplate(t) : `${Object.keys(t.project_data || {}).length} fields`}
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => apply(t)}
                  className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
                >
                  Apply
                </button>
                <button type="button" onClick={() => remove(t)} className="text-gray-400 hover:text-red-600">
                  <Trash2 className="w-4 h-4" aria-hidden="true" />
                </button>
              </div>
            ))}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { snapshotHash } from "@/components/estimator/builder/builderService";
import { instantiateProductSnapshot } from "@/components/estimator/products/quickProductService";
import { cloneSnapshot } from "@/components/estimator/products/snapshotUtils";
import { addPartPackageToProduct } from "@/components/estimator/parts/partPackageService";
import { acceptedCustomerUnitPrice, liveCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { builderMutationHash } from "@/components/estimator/builder/builderMutationRecovery";
import { ensureReusableRecord } from "@/components/estimator/products/reusableSaveIdempotency";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { deleteEntityIfUnchanged, expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const nowIso = () => new Date().toISOString();
const expiryIso = () => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

async function getEstimateLine(estimate, builderProductId) {
  return (estimate?.line_items || []).find((line) => line.builder_product_id === builderProductId) || null;
}

function sourceMeta(estimate, line) {
  return {
    source_estimate_id: estimate?.id || "",
    source_estimate_number: estimate?.estimate_number || "",
    source_order: estimate?.po_number || estimate?.work_order_id || "",
    source_company: estimate?.client_name || "",
    source_product_id: line?.builder_product_id || "",
    source_product_name: line?.client_product_name || line?.project_name || "",
    source_module_key: line?.module_key || "",
  };
}

async function captureProductPayload({ line }) {
  const [builder, parts, groups] = await Promise.all([
    staffEntities.BuilderProduct.get(line.builder_product_id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: line.builder_product_id }, sort: "sort_order", label: "Clipboard Product Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: line.builder_product_id }, sort: "sort_order", label: "Clipboard Product Part Groups" }),
  ]);
  if (!builder) throw new Error("Product could not be loaded for clipboard copy.");
  const activeParts = (parts || []).filter((part) => part.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  const activeGroups = (groups || []).filter((group) => group.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  const frozenTotal = num(builder.frozen_cost, num(line.total_snapshot));
  const currentTotal = num(builder.current_recalculated_cost, num(line.live_total_snapshot, frozenTotal));
  const frozenCustomerPrice = num(builder.frozen_customer_price, acceptedCustomerUnitPrice(line));
  const currentCustomerPrice = liveCustomerUnitPrice(line);
  return {
    product_name: line.client_product_name || builder.client_product_name || line.project_name || "Product",
    template_version: 2,
    source_product_class: line.module_key === "custom" ? "custom" : "builder",
    source_module_key: line.module_key || builder.module_key || "custom",
    source_entity: builder.source_entity || "",
    source_builder_name: builder.builder_name || line.builder_name || "Custom Product",
    product_category: line.product_category || builder.product_category || "",
    production_product_type: line.production_product_type ?? builder.production_product_type ?? "",
    product_group: "my",
    categories: line.product_category ? [line.product_category] : [],
    product_quantity: num(line.customer_quantity, num(builder.quantity, 1)),
    is_active: true,
    product_notes: line.product_notes ?? builder.product_notes ?? "",
    client_description: line.customer_description ?? builder.client_description ?? "",
    product_snapshot: { line: cloneSnapshot(line), builder_product: cloneSnapshot(builder) },
    builder_snapshot: cloneSnapshot(builder.builder_snapshot || {}),
    builder_snapshot_hash: builder.builder_snapshot_hash || snapshotHash(builder.builder_snapshot || {}),
    parts_snapshot: activeParts.map(cloneSnapshot),
    part_groups_snapshot: activeGroups.map((group) => ({ ...cloneSnapshot(group), snapshot_source_group_id: group.id })),
    price_snapshot: {
      frozen_cost: frozenTotal,
      frozen_customer_price: frozenCustomerPrice,
      current_recalculated_cost: currentTotal,
      current_recalculated_customer_price: currentCustomerPrice,
      price_state: builder.price_state || line.price_state || "current",
      price_delta: num(builder.price_delta, currentTotal - frozenTotal),
      price_delta_percent: num(builder.price_delta_percent),
      price_recalc_required: !!(builder.price_recalc_required || line.price_recalc_required),
      price_recalc_reason: builder.price_recalc_reason || line.price_recalc_reason || "",
      captured_at: nowIso(),
    },
    detached_part_count: num(builder.detached_part_count),
    needs_reattach_review: !!builder.needs_reattach_review,
    total_price: frozenCustomerPrice,
  };
}

async function createClipboardRecord(data) {
  const keyPayload = cloneSnapshot(data.payload || {});
  if (keyPayload?.price_snapshot && typeof keyPayload.price_snapshot === "object") {
    delete keyPayload.price_snapshot.captured_at;
  }
  const idempotencyKey = `estimate_clipboard_copy:${builderMutationHash({
    item_type: data.item_type || "",
    item_name: data.item_name || "",
    source_estimate_id: data.source_estimate_id || "",
    source_product_id: data.source_product_id || "",
    source_part_group_id: data.source_part_group_id || "",
    source_part_id: data.source_part_id || "",
    payload: keyPayload,
    notes: data.notes || "",
  })}`;
  const copiedAt = nowIso();
  const expiresAt = expiryIso();
  const searchText = [data.item_name, data.source_estimate_number, data.source_order, data.source_company, data.source_product_name, data.source_module_key]
    .filter(Boolean).join(" ").toLowerCase();
  const record = await ensureReusableRecord({
    entity: staffEntities.EstimateClipboardItem,
    idempotencyKey,
    label: "Estimator clipboard item",
    data: {
      ...data,
      copied_at: copiedAt,
      expires_at: expiresAt,
      is_active: true,
      search_text: searchText,
    },
  });
  if (!record?.id) return record;
  const refreshPatch = {
    copied_at: copiedAt,
    expires_at: expiresAt,
    is_active: true,
    search_text: searchText,
  };
  return replaceEntityFieldsIfUnchanged({
    entity: staffEntities.EstimateClipboardItem,
    id: record.id,
    expectedUpdatedAt: record.updated_date || "",
    expectedFields: expectedEntityFields(record, refreshPatch),
    nextFields: refreshPatch,
    label: "Estimator clipboard refresh",
  });
}

export async function copyProductToClipboard({ estimateId, line }) {
  if (!estimateId || !line?.builder_product_id) throw new Error("Product is not ready to copy.");
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  const payload = await captureProductPayload({ line });
  return createClipboardRecord({
    item_type: "product",
    item_name: payload.product_name,
    ...sourceMeta(estimate, line),
    payload,
    notes: "Complete Product package: Builder, Parts, Part Groups, snapshots and frozen pricing.",
  });
}

export async function copyPartToClipboard({ estimateId, builderProductId, part }) {
  if (!estimateId || !builderProductId || !part) throw new Error("Part is not ready to copy.");
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  const line = await getEstimateLine(estimate, builderProductId);
  return createClipboardRecord({
    item_type: "part",
    item_name: part.client_label || part.part_name || "Part",
    ...sourceMeta(estimate, line),
    source_part_id: part.id || "",
    payload: { part: cloneSnapshot(part) },
    notes: "Complete Part snapshot with Master Inventory links and frozen/current pricing.",
  });
}

export async function copyPartGroupToClipboard({ estimateId, builderProductId, group, parts }) {
  if (!estimateId || !builderProductId || !group) throw new Error("Part Group is not ready to copy.");
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  const line = await getEstimateLine(estimate, builderProductId);
  return createClipboardRecord({
    item_type: "part_group",
    item_name: group.group_name || "Part Group",
    ...sourceMeta(estimate, line),
    source_part_group_id: group.id || "",
    payload: {
      group: { ...cloneSnapshot(group), snapshot_source_group_id: group.id },
      parts: (parts || []).filter((part) => part.is_active !== false).map(cloneSnapshot),
    },
    notes: `Part Group snapshot with ${(parts || []).length} Parts.`,
  });
}

export async function listClipboardItems() {
  const rows = await loadAllEntityRows({ entity: staffEntities.EstimateClipboardItem, sort: "-copied_at", label: "Estimator Clipboard" });
  const now = Date.now();
  const currentRows = [];
  for (const row of rows || []) {
    const expired = row.expires_at && new Date(row.expires_at).getTime() <= now;
    if (!expired) {
      currentRows.push(row);
      continue;
    }
    try {
      await deleteEntityIfUnchanged({
        entity: staffEntities.EstimateClipboardItem,
        record: row,
        label: "Expired estimator clipboard item",
      });
    } catch {
      // A refreshed clipboard item must never be deleted using a stale expiry
      // snapshot. Re-read it and keep the newer live row when it is still usable.
      const current = await staffEntities.EstimateClipboardItem.get(row.id).catch(() => null);
      if (current) currentRows.push(current);
    }
  }
  return currentRows
    .filter((row) => row.is_active !== false && (!row.expires_at || new Date(row.expires_at).getTime() > now))
    .sort((a, b) => new Date(b.copied_at || b.created_date || 0) - new Date(a.copied_at || a.created_date || 0));
}

// Mirrors the canonical not-found detection in builderEntityPersistence
// (isEntityNotFoundError): a genuinely-missing record is "already gone" while
// every other fetch failure stays an error so the clipboard never drops a
// live row. All message fields are scanned (not just the first) so a generic
// top-level message cannot hide a nested "not found" detail.
const isNotFound = (e) => {
  const status = Number(e?.status || e?.response?.status || e?.response?.statusCode || e?.data?.status || 0);
  if (status === 404) return true;
  const message = [
    e?.message,
    e?.response?.data?.message,
    e?.response?.data?.error,
    e?.data?.message,
    e?.data?.error,
  ].map((v) => String(v || "").toLowerCase()).join(" ");
  return message.includes("not found") || message.includes("does not exist");
};

export async function removeClipboardItem(id) {
  const itemId = String(id || "").trim();
  if (!itemId) return;
  let current;
  try {
    current = await staffEntities.EstimateClipboardItem.get(itemId);
  } catch (e) {
    // Only a definitive not-found is "already gone". A transient read error
    // (500/429/timeout) must rethrow — the caller only filters the row out of
    // the list after a confirmed removal, so it can never stale-remove a row
    // that still exists.
    if (isNotFound(e)) return;
    throw e;
  }
  if (!current) return;
  await deleteEntityIfUnchanged({
    entity: staffEntities.EstimateClipboardItem,
    record: current,
    label: "Estimator clipboard item",
  });
}

export async function pasteClipboardItem({ estimateId, clipboardItem, targetBuilderProductId = "", expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !clipboardItem?.id) throw new Error("Clipboard item is required.");
  const liveItem = await staffEntities.EstimateClipboardItem.get(clipboardItem.id);
  if (!liveItem) throw new Error("This clipboard item no longer exists. Reopen the Estimator Clipboard to refresh it.");
  if (liveItem.is_active === false) throw new Error("This clipboard item is inactive and cannot be pasted.");
  if (liveItem.expires_at && new Date(liveItem.expires_at).getTime() <= Date.now()) {
    throw new Error("This clipboard item has expired. Reopen the Estimator Clipboard to refresh it.");
  }
  if (clipboardItem.updated_date && liveItem.updated_date && clipboardItem.updated_date !== liveItem.updated_date) {
    throw new Error("This clipboard item changed after the clipboard opened. Reopen it before pasting.");
  }
  if (liveItem.item_type === "product") {
    return instantiateProductSnapshot({ estimateId, productSnapshot: liveItem.payload, expectedEstimateUpdatedAt, sourceId: liveItem.id });
  }
  return addPartPackageToProduct({
    estimateId,
    targetBuilderProductId,
    itemType: liveItem.item_type,
    itemName: liveItem.item_name,
    payload: liveItem.payload,
    sourceType: "clipboard",
    sourceId: liveItem.id,
    expectedEstimateUpdatedAt,
  });
}

import { useEffect, useMemo, useRef, useState } from "react";
import { ClipboardPaste, Package, Search, Trash2 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { listClipboardItems, pasteClipboardItem, removeClipboardItem } from "@/components/estimator/products/clipboardService";

const typeLabel = (type) => type === "part_group" ? "Part Group" : type === "part" ? "Part" : "Product";
const daysLeft = (date) => Math.max(0, Math.ceil((new Date(date).getTime() - Date.now()) / 86400000));

export default function ClipboardManagerModal({ open, estimateId, expectedEstimateUpdatedAt = "", lines = [], onClose, onPasted }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [query, setQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [targetByItem, setTargetByItem] = useState({});
  const [busyId, setBusyId] = useState("");
  const [loadError, setLoadError] = useState("");
  const [error, setError] = useState("");
  const pasteRef = useRef(false);

  const load = async () => {
    setLoading(true);
    setLoadError("");
    setError("");
    setItems([]);
    try {
      setItems(await listClipboardItems());
    } catch (err) {
      setLoadError(err?.message || "Clipboard could not be loaded.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!open) return;
    setQuery("");
    setTypeFilter("all");
    setTargetByItem({});
    load();
  }, [open]);

  const targets = (lines || []).filter((line) => !!line.builder_product_id);
  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return items.filter((item) => {
      if (typeFilter !== "all" && item.item_type !== typeFilter) return false;
      if (!q) return true;
      const haystack = `${item.item_name || ""} ${item.search_text || ""} ${item.source_product_name || ""}`.toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    });
  }, [items, query, typeFilter]);

  const paste = async (item) => {
    if (!item?.id || pasteRef.current) return;
    pasteRef.current = true;
    const targetBuilderProductId = item.item_type === "product" ? "" : (targetByItem[item.id] || targets[0]?.builder_product_id || "");
    if (item.item_type !== "product" && !targetBuilderProductId) {
