                          <button type="button" disabled={!!busyId} onClick={() => remove(item)} className="w-[30px] h-[30px] rounded border border-red-200 bg-white text-red-500 hover:bg-red-50 flex items-center justify-center" title="Remove from clipboard" aria-label={`Remove ${item.item_name || "item"} from clipboard`}><Trash2 className="w-3.5 h-3.5" aria-hidden="true" /></button>
