import { copyPartGroupToClipboard, copyPartToClipboard } from "@/components/estimator/products/clipboardService";
import { clonePartGroupInProduct, createPartGroupInProduct, dissolvePartGroup, moveIndependentPartGroup, renamePartGroup } from "@/components/estimator/parts/partGroupService";
import { expectedBuilderEntityFields, replaceBuilderEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import MovePartGroupModal from "./MovePartGroupModal";
import SavePartTemplateModal from "@/components/estimator/parts/SavePartTemplateModal";
import PartLibraryPickerModal from "@/components/estimator/parts/PartLibraryPickerModal";
import VendorCostBadge from "@/components/estimator/VendorCostBadge";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

const num = (value, fallback = 0) =>
  Number.isFinite(Number(value)) ? Number(value) : fallback;

// (#407) Large part lists render in chunks of PART_ROW_PAGE so a 300-part
// product doesn't mount hundreds of PartRow trees at once. A "Show more"
// control reveals the next chunk; searching bypasses the window so every
// match stays reachable.
const PART_ROW_PAGE = 100;

const typeLabel = (part) =>
  String(part?.part_type || "part")
    .replaceAll("_", " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());

const priceStateMeta = (part) => {
  if (["detached", "reattach_available"].includes(part.inventory_link_state) || part.price_state === "detached") {
    return { label: "Detached", className: "bg-amber-50 text-amber-700 border-amber-200", icon: Unlink };
  }
  if (part.price_state === "changed") {
    return { label: "Price updated", className: "bg-amber-50 text-amber-700 border-amber-200", icon: AlertTriangle };
  }
  if (part.price_state === "legacy_frozen") {
    return { label: "Frozen legacy price", className: "bg-slate-100 text-slate-600 border-slate-200", icon: LockKeyhole };
  }
  return { label: "Price current", className: "bg-green-50 text-green-700 border-green-200", icon: Link2 };
};

function PartRow({ part, index, selectionMode = false, selected = false, onSelect, onChanged, onEditBuilder, estimateId, expectedEstimateUpdatedAt = "", readOnly = false }) {
  const [open, setOpen] = useState(false);
  const [warningOpen, setWarningOpen] = useState(false);
  const [overrideOpen, setOverrideOpen] = useState(false);
  const [switchOpen, setSwitchOpen] = useState(false);
  const [copying, setCopying] = useState(false);
  const [copied, setCopied] = useState(false);
  const [saveLibraryOpen, setSaveLibraryOpen] = useState(false);
  const frozen = num(part.frozen_extended_cost);
  const current = num(part.current_extended_cost, frozen);
  const differs = Math.abs(current - frozen) > 0.005;
  const meta = priceStateMeta(part);
  const StatusIcon = meta.icon;
  const isManual = part.builder_sync_state === "manual";
  const isManualAddon = part.builder_sync_state === "manual_addon";
  const isDetachedOverride = part.builder_sync_state === "detached_override";
  const isDirectlyEditable = isManual || isManualAddon;
  const isIndependent = isDirectlyEditable || isDetachedOverride;
  const inventoryDetails = typeDetails(part.inventory_entity, part.frozen_inventory_snapshot || {}, part.detail_overrides || {});

  return (
    <div className="border border-gray-200 rounded-sm bg-white overflow-hidden">
      <div className="w-full min-h-[42px] px-3 py-2 flex items-center gap-2 text-left hover:bg-gray-50">
        {selectionMode && (
          <input
            type="checkbox"
            checked={selected}
            onChange={(event) => onSelect?.(part.id, event.target.checked)}
            className="h-4 w-4 rounded border-gray-300 accent-lime-500 flex-shrink-0"
            aria-label={`Select ${part.part_name || "Part"}`}
          />
        )}
        <button
          type="button"
          onClick={() => setOpen((value) => !value)}
          aria-expanded={open}
          className="flex-1 min-w-0 flex items-center gap-2 text-left"
        >
        {open ? <ChevronDown className="w-3.5 h-3.5 text-gray-500" aria-hidden="true" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-500" aria-hidden="true" />}
        <Box className="w-3.5 h-3.5 text-gray-400" aria-hidden="true" />
        <span className="text-[9px] font-bold tracking-wider text-gray-400 w-[52px] flex-shrink-0">PART {String(index + 1).padStart(2, "0")}</span>
        <span className="text-[12px] font-semibold text-gray-900 truncate flex-1">{part.client_label || part.part_name || "Part"}</span>
        <span className="hidden md:inline text-[10px] text-gray-500 px-2 py-0.5 rounded bg-gray-100">{typeLabel(part)}</span>
        <span className={`hidden sm:inline-flex items-center gap-1 text-[9px] px-2 py-0.5 rounded-full border ${meta.className}`}>
          <StatusIcon className="w-3 h-3" aria-hidden="true" /> {meta.label}
        </span>
          <div className="text-right w-[92px] flex-shrink-0">
            <div className="text-[11px] font-bold text-gray-800">{money(frozen)}</div>
            {differs && <div className="text-[9px] text-amber-600">current {money(current)}</div>}
          </div>
        </button>
      </div>

      {/* F-21: vended-part vendor cost/markup strip — renders only when the
          part resolves as vended; Edit reuses the row's own edit path. */}
      <VendorCostBadge
        part={part}
        onEdit={readOnly ? null : () => (isIndependent ? setOverrideOpen(true) : setWarningOpen(true))}
      />

      {open && (
        <div className="border-t border-gray-200 bg-gray-50 px-3 py-3">
          <div className="flex items-center justify-between gap-2 mb-3">
            <div className="text-[10px] text-gray-500">
              {isManual ? "Custom Product Part — edit directly or keep tracking its Master Inventory price." : isManualAddon ? "Independent add-on Part — not controlled by this Builder and safe from Builder recalculation." : isDetachedOverride ? "Independent override — Builder synchronization is disabled." : "Builder-linked Part — edit through the Builder or detach it first."}
              {isDetachedOverride && part.builder_detached_at && (
                <div className="text-[10px] text-amber-700 mt-0.5">
                  Detached {new Date(part.builder_detached_at).toLocaleString()}{part.builder_detached_by ? ` by ${part.builder_detached_by}` : ""}{part.builder_detached_reason ? ` — ${part.builder_detached_reason}` : ""}
                </div>
              )}
            </div>
            <div className="flex items-center gap-1.5">
              {estimateId && (
                <button
                  type="button"
                  disabled={copying}
                  onClick={async () => {
                    setCopying(true);
                    try {
                      await copyPartToClipboard({ estimateId, builderProductId: part.builder_product_id, part });
                      setCopied(true);
                      setTimeout(() => setCopied(false), 1500);
                    } catch (error) {
                      window.alert(error?.message || "Part could not be copied to the estimator clipboard.");
                    } finally {
                      setCopying(false);
                    }
                  }}
                  className="h-[28px] px-2.5 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1 disabled:opacity-50"
                  title="Copy Part to 30-day Clipboard"
                  aria-label={`Copy ${part.part_name || "Part"} to 30-day clipboard`}
                ><ClipboardCopy className="w-3 h-3" aria-hidden="true" /> {copied ? "Copied" : "Copy"}</button>
              )}
              <button type="button" onClick={() => setSaveLibraryOpen(true)} className="h-[28px] px-2.5 rounded border border-violet-200 bg-white text-[11px] font-semibold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1" title="Save Part permanently to Part Library" aria-label={`Save ${part.part_name || "Part"} permanently to Part Library`}><BookmarkPlus className="w-3 h-3" aria-hidden="true" /> Save</button>
              {!readOnly && isDirectlyEditable && (
                <button type="button" onClick={() => setSwitchOpen(true)} className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1"><RefreshCw className="w-3 h-3" aria-hidden="true" /> Switch Part</button>
              )}
              {!readOnly && (
                <button
                  type="button"
                  onClick={() => isIndependent ? setOverrideOpen(true) : setWarningOpen(true)}
                  className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100"
                >
                  {isDetachedOverride ? "Edit Override" : "Edit Part"}
                </button>
              )}
              {!readOnly && isDirectlyEditable && (
                <button type="button" onClick={async () => { if (!window.confirm(`Remove "${part.part_name || "Part"}" from this Product?`)) return; await removeManualProductPart(part.id, { builderProductId: part.builder_product_id, expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" }); await onChanged?.(); }} className="h-[28px] px-2.5 rounded border border-red-200 bg-white text-[11px] font-semibold text-red-600 hover:bg-red-50" title="Remove Part" aria-label={`Remove ${part.part_name || "Part"} from this Product`}><Trash2 className="w-3 h-3" aria-hidden="true" /></button>
              )}
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-3">
          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PART INFORMATION</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Type</dt><dd className="font-medium text-gray-800 text-right">{typeLabel(part)}</dd></div>
              {part.part_subtype && <div className="flex justify-between gap-3"><dt className="text-gray-500">Subtype</dt><dd className="font-medium text-gray-800 text-right">{String(part.part_subtype).replaceAll("_", " ")}</dd></div>}
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Quantity</dt><dd className="font-medium text-gray-800 text-right">{num(part.quantity, 1).toLocaleString()} {part.unit || ""}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Builder source</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.source_module_key || "Manual"}</dd></div>
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">MASTER INVENTORY LINK</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Status</dt><dd className="font-medium text-right">{part.inventory_link_state === "manual" ? "Manual / Builder cost" : String(part.inventory_link_state || "manual").replaceAll("_", " ")}</dd></div>
              {part.inventory_item_name && <div className="flex justify-between gap-3"><dt className="text-gray-500">Inventory Part</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.inventory_item_name}</dd></div>}
              {part.inventory_entity && <div className="flex justify-between gap-3"><dt className="text-gray-500">Inventory Type</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.inventory_entity}</dd></div>}
              {part.reattach_candidate_name && <div className="flex justify-between gap-3"><dt className="text-gray-500">Suggested match</dt><dd className="font-medium text-lime-700 text-right truncate max-w-[190px]">{part.reattach_candidate_name}</dd></div>}
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PRICING INFORMATION</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Frozen unit cost</dt><dd className="font-semibold text-gray-800">{money(num(part.frozen_unit_cost))}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Frozen extended</dt><dd className="font-semibold text-gray-800">{money(frozen)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Current unit cost</dt><dd className={differs ? "font-semibold text-amber-700" : "font-semibold text-gray-800"}>{money(num(part.current_unit_cost, num(part.frozen_unit_cost)))}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Current extended</dt><dd className={differs ? "font-semibold text-amber-700" : "font-semibold text-gray-800"}>{money(current)}</dd></div>
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">TYPE-SPECIFIC DETAILS</div>
            {inventoryDetails.length ? (
              <dl className="space-y-1.5 text-[11px] max-h-[170px] overflow-y-auto pr-1">
                {inventoryDetails.map((detail) => (
                  <div key={detail.field} className="flex justify-between gap-3 border-b border-gray-50 pb-1 last:border-b-0">
                    <dt className="text-gray-500 flex items-center gap-1">{detail.label}{detail.overridden && <span className="text-[8px] px-1 rounded bg-amber-100 text-amber-700 border border-amber-200">OVERRIDE</span>}</dt>
                    <dd className="font-medium text-gray-800 text-right max-w-[190px] break-words">
                      {Array.isArray(detail.value) ? detail.value.join(", ") : String(detail.value).replaceAll("_", " ")}
                    </dd>
                  </div>
                ))}
              </dl>
            ) : (
              <div className="text-[10px] text-gray-400">No additional type-specific inventory fields for this Part.</div>
            )}
          </section>
          </div>
        </div>
      )}

      <BuilderPartEditWarningModal
        open={warningOpen}
        part={part}
        onCancel={() => setWarningOpen(false)}
        onEditBuilder={() => {
          setWarningOpen(false);
          onEditBuilder?.();
        }}
        onDetach={async () => {
          await detachBuilderPartOverride(part.id, undefined, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          setWarningOpen(false);
          setOverrideOpen(true);
          await onChanged?.();
        }}
      />
      <DetachedPartOverrideModal
        open={overrideOpen}
        part={part}
        mode={isDirectlyEditable ? "manual" : "detached"}
        onClose={() => setOverrideOpen(false)}
        onSave={async (changes) => {
          if (isDirectlyEditable) await updateManualProductPart(part.id, changes, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          else await updateDetachedPartOverride(part.id, changes, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          setOverrideOpen(false);
          await onChanged?.();
        }}
      />
      <SavePartTemplateModal
        open={saveLibraryOpen}
        itemType="part"
        part={part}
        estimateId={estimateId}
        builderProductId={part.builder_product_id}
        onClose={() => setSaveLibraryOpen(false)}
      />
      {isDirectlyEditable && (
        <MasterPartPickerModal
          open={switchOpen}
          mode="switch"
          suggestQuery={part.part_name || part.inventory_item_name || ""}
          initialQuantity={part.quantity || 1}
          onClose={() => setSwitchOpen(false)}
          onAdd={async (item) => {
            await switchManualProductPart(part.id, item, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
            setSwitchOpen(false);
            await onChanged?.();
          }}
        />
      )}
    </div>
  );
}

function PartGroup({ group, parts, globalOffset, selectionMode, selectedIds, onSelect, onChanged, builderProductId, onEditBuilder, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [open, setOpen] = useState(!group.is_collapsed);
  const [visibleParts, setVisibleParts] = useState(PART_ROW_PAGE);
  const [renaming, setRenaming] = useState(false);
  const [name, setName] = useState(group.group_name || "Part Group");
  const [copying, setCopying] = useState(false);
  const [copied, setCopied] = useState(false);
  const [cloning, setCloning] = useState(false);
  const [moveOpen, setMoveOpen] = useState(false);
  const [saveLibraryOpen, setSaveLibraryOpen] = useState(false);
  const structuralActionRef = useRef(false);
  const groupVersionRef = useRef(group.updated_date || "");
  useEffect(() => {
    groupVersionRef.current = group.updated_date || groupVersionRef.current;
  }, [group.updated_date]);
  const frozen = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const canMove = parts.length > 0 && parts.every((part) => ["manual", "manual_addon"].includes(part.builder_sync_state));
  const moveTargets = (availableProducts || []).filter((line) => line.builder_product_id && line.builder_product_id !== builderProductId);

  const toggleOpen = async () => {
    const next = !open;
    setOpen(next);
    if (!readOnly) {
      let current;
      try {
        current = await base44.entities.BuilderPartGroup.get(group.id);
      } catch (error) {
        // Transient pre-read failure — the optimistic toggle would diverge
        // from persisted is_collapsed, so revert it and surface the error.
        setOpen(!next);
        window.alert(`Part Group collapsed state could not be saved.${error?.message ? `\n\n${error.message}` : ""}`);
        return;
      }
      if (!current?.id || current.builder_product_id !== builderProductId) return;
      const collapsePatch = { is_collapsed: !next };
      let updated;
      try {
        updated = await replaceBuilderEntityFieldsIfUnchanged({
          entity: base44.entities.BuilderPartGroup,
          id: group.id,
          expectedUpdatedAt: current.updated_date || "",
          expectedFields: expectedBuilderEntityFields(current, collapsePatch),
          nextFields: collapsePatch,
          guardFields: { builder_product_id: builderProductId },
          label: "Part Group collapsed state",
        });
      } catch (error) {
        // Same rule as the pre-read — a swallowed write failure leaves the UI
        // showing a collapsed state the record does not hold until reload.
        setOpen(!next);
        window.alert(`Part Group collapsed state could not be saved.${error?.message ? `\n\n${error.message}` : ""}`);
        return;
      }
      if (updated?.updated_date) groupVersionRef.current = updated.updated_date;
      else if (current?.updated_date) groupVersionRef.current = current.updated_date;
    }
  };

  const saveName = async () => {
    if (structuralActionRef.current) return;
    structuralActionRef.current = true;
    const nextName = name.trim() || "Part Group";
    setName(nextName);
    setRenaming(false);
    try {
      await renamePartGroup({
        builderProductId,
        groupId: group.id,
        groupName: nextName,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
      });
      await onChanged?.();
    } catch (error) {
      window.alert(error?.message || "Part Group could not be renamed.");
    } finally {
      structuralActionRef.current = false;
    }
  };

  const dissolve = async () => {
    if (structuralActionRef.current) return;
    if (!window.confirm(`Dissolve "${group.group_name || "Part Group"}"? The Parts will stay in this Product and keep all frozen pricing.`)) return;
    structuralActionRef.current = true;
    try {
      await dissolvePartGroup({
        builderProductId,
        groupId: group.id,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
        expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
      });
      await onChanged?.();
    } catch (error) {
      await Promise.resolve(onChanged?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be dissolved."}\n\nThe Product was refreshed. If the dissolve had already started, use Resume Group Dissolve to safely continue it.`);
    } finally {
      structuralActionRef.current = false;
    }
  };

  return (
    <div className="border border-gray-300 rounded-sm overflow-hidden bg-gray-50">
      <div className="w-full px-3 py-2 flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-left">
        <button type="button" onClick={toggleOpen} aria-expanded={open} className="flex items-center gap-2 min-w-0 flex-1 text-left">
        {open ? <ChevronDown className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" />}
        <Layers3 className="w-4 h-4 text-gray-600" aria-hidden="true" />
          <span className="text-[9px] font-extrabold tracking-widest text-gray-500">PART GROUP</span>
          {renaming ? (
            <input
              autoFocus
              value={name}
              onChange={(event) => setName(event.target.value)}
              onClick={(event) => event.stopPropagation()}
              aria-label="Part Group name"
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  saveName();
                }
                if (event.key === "Escape") {
                  setName(group.group_name || "Part Group");
                  setRenaming(false);
                }
              }}
              onBlur={saveName}
              className="h-[25px] px-2 border border-gray-300 rounded bg-white text-[12px] font-bold text-gray-900 flex-1 min-w-[120px]"
            />
          ) : (
            <span className="text-[12px] font-bold text-gray-900 truncate flex-1">{group.group_name || "Part Group"}</span>
          )}
          <span className="text-[10px] text-gray-500">{parts.length} parts</span>
          <span className="text-[11px] font-bold text-gray-800 w-[92px] text-right">{money(frozen)}</span>
        </button>
        {!selectionMode && (
          <div className="flex items-center gap-1 ml-1">
            {estimateId && (
              <button
                type="button"
                disabled={copying}
                onClick={async () => {
                  setCopying(true);
                  try {
                    await copyPartGroupToClipboard({ estimateId, builderProductId, group, parts });
                    setCopied(true);
                    setTimeout(() => setCopied(false), 1500);
                  } catch (error) {
                    window.alert(error?.message || "Part Group could not be copied to the estimator clipboard.");
                  } finally {
                    setCopying(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Copy Part Group to 30-day Clipboard"
                aria-label={`Copy ${group.group_name || "Part Group"} to 30-day clipboard`}
              ><ClipboardCopy className="w-3 h-3" aria-hidden="true" /> {copied ? "Copied" : "Copy"}</button>
            )}
            <button
              type="button"
              onClick={() => setSaveLibraryOpen(true)}
              className="h-[26px] px-2 rounded border border-violet-200 bg-white flex items-center gap-1 text-[10px] font-semibold text-violet-700 hover:bg-violet-50"
              title="Save Part Group permanently to Part Library"
              aria-label={`Save ${group.group_name || "Part Group"} permanently to Part Library`}
            ><BookmarkPlus className="w-3 h-3" aria-hidden="true" /> Save</button>
            {!readOnly && <>
              <button
                type="button"
                disabled={cloning}
                onClick={async () => {
                  if (!window.confirm(`Clone "${group.group_name || "Part Group"}" and all ${parts.length} Part${parts.length === 1 ? "" : "s"}?`)) return;
                  if (structuralActionRef.current) return;
                  structuralActionRef.current = true;
                  setCloning(true);
                  try {
                    await clonePartGroupInProduct({
                      builderProductId,
                      groupId: group.id,
                      expectedEstimateUpdatedAt,
                      expectedGroupUpdatedAt: groupVersionRef.current,
                      expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
                    });
                    await onChanged?.();
                  } catch (error) {
                    await Promise.resolve(onChanged?.()).catch(() => null);
                    window.alert(`${error?.message || "Part Group could not be cloned."}\n\nThe Product was refreshed. If the clone had already started, use Resume Group Clone to safely continue it.`);
                  } finally {
                    structuralActionRef.current = false;
                    setCloning(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Clone Part Group in this Product"
                aria-label={`Clone ${group.group_name || "Part Group"} in this Product`}
              ><CopyPlus className="w-3 h-3" aria-hidden="true" /> {cloning ? "Cloning…" : "Clone"}</button>
              <button
                type="button"
                disabled={!canMove || moveTargets.length === 0}
                onClick={() => setMoveOpen(true)}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-40"
                title={canMove ? "Move Part Group to another Product" : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
                aria-label={canMove ? `Move ${group.group_name || "Part Group"} to another Product` : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
              ><ArrowRightLeft className="w-3 h-3" aria-hidden="true" /> Move</button>
              <button
                type="button"
                onClick={() => setRenaming(true)}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-600 hover:bg-gray-50"
                title="Rename Part Group"
                aria-label={`Rename ${group.group_name || "Part Group"}`}
              >
                <Pencil className="w-3 h-3" aria-hidden="true" />
              </button>
              <button
                type="button"
                onClick={dissolve}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-500 hover:text-red-600 hover:bg-red-50"
                title="Dissolve Part Group"
                aria-label={`Dissolve ${group.group_name || "Part Group"}`}
              >
                <Unlink className="w-3 h-3" aria-hidden="true" />
              </button>
            </>}
          </div>
        )}
      </div>
      {open && (
        <div className="p-2 space-y-2 border-t border-gray-200">
          {parts.slice(0, visibleParts).map((part, index) => (
            <PartRow
              key={part.id}
              part={part}
              index={globalOffset + index}
              selectionMode={selectionMode}
              selected={selectedIds.has(part.id)}
              onSelect={onSelect}
              onChanged={onChanged}
              onEditBuilder={onEditBuilder}
              estimateId={estimateId}
              expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
              readOnly={readOnly}
            />
          ))}
          {parts.length > visibleParts && (
            <button
              type="button"
              onClick={() => setVisibleParts((value) => value + PART_ROW_PAGE)}
              className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
            >
              Show {Math.min(PART_ROW_PAGE, parts.length - visibleParts)} more parts ({parts.length - visibleParts} remaining)
            </button>
          )}
        </div>
      )}
      <MovePartGroupModal
        open={moveOpen}
        group={group}
        sourceBuilderProductId={builderProductId}
        products={moveTargets}
        onClose={() => setMoveOpen(false)}
        onMove={async (targetBuilderProductId) => {
          if (structuralActionRef.current) return;
          structuralActionRef.current = true;
          try {
            await moveIndependentPartGroup({
              sourceBuilderProductId: builderProductId,
              targetBuilderProductId,
              groupId: group.id,
              expectedEstimateUpdatedAt,
              expectedGroupUpdatedAt: groupVersionRef.current,
              expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
            });
            setMoveOpen(false);
            await onChanged?.();
          } catch (error) {
            await Promise.resolve(onChanged?.()).catch(() => null);
            throw new Error(`${error?.message || "Part Group could not be moved."}\n\nThe Products were refreshed. If the move had already started, use Resume Group Move to safely continue it.`);
          } finally {
            structuralActionRef.current = false;
          }
        }}
      />
      <SavePartTemplateModal
        open={saveLibraryOpen}
        itemType="part_group"
        group={group}
        parts={parts}
        estimateId={estimateId}
        builderProductId={builderProductId}
        onClose={() => setSaveLibraryOpen(false)}
      />
    </div>
  );
}

export default function BuilderPartsPanel({ builderProductId, refreshKey, onLoaded, onEditBuilder, onProductRefresh, allowAddParts = false, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [loading, setLoading] = useState(!!builderProductId);
  const [parts, setParts] = useState([]);
  const [groups, setGroups] = useState([]);
  const [dragGroupIdx, setDragGroupIdx] = useState(null);
  const [dragOverIdx, setDragOverIdx] = useState(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [groupModalOpen, setGroupModalOpen] = useState(false);
  const [partPickerOpen, setPartPickerOpen] = useState(false);
  const [partLibraryOpen, setPartLibraryOpen] = useState(false);
  const [refreshNonce, setRefreshNonce] = useState(0);
  const [partSearch, setPartSearch] = useState("");
  const [ungroupedVisible, setUngroupedVisible] = useState(PART_ROW_PAGE);
  const [bulkRemoving, setBulkRemoving] = useState(false);
  const [bulkDetaching, setBulkDetaching] = useState(false);
  const groupCreateRef = useRef(false);

  useEffect(() => {
    let active = true;
    const load = async () => {
      if (!builderProductId) {
        setParts([]);
        setGroups([]);
        setLoading(false);
        onLoaded?.(0);
        return;
      }
      setLoading(true);
      try {
        const [partRows, groupRows] = await Promise.all([
          loadAllEntityRows({ entity: base44.entities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Parts" }),
          loadAllEntityRows({ entity: base44.entities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Groups" }),
        ]);
        if (!active) return;
        const activeParts = (partRows || [])
          .filter((part) => part.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        const activeGroups = (groupRows || [])
          .filter((group) => group.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        setParts(activeParts);
        setGroups(activeGroups);
        onLoaded?.(activeParts.length);
      } finally {
        if (active) setLoading(false);
      }
    };
    load();
    return () => {
      active = false;
    };
  }, [builderProductId, refreshKey, refreshNonce]);

  const togglePartSelection = (partId, checked) => {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (checked) next.add(partId);
      else next.delete(partId);
      return next;
    });
  };

  const cancelSelection = () => {
    setSelectionMode(false);
    setSelectedIds(new Set());
    setGroupModalOpen(false);
  };

  const removableSelected = parts.filter((part) => selectedIds.has(part.id) && ["manual", "manual_addon"].includes(part.builder_sync_state));

  const bulkRemoveSelected = async () => {
    if (!builderProductId || bulkRemoving || !removableSelected.length) return;
    const skipped = selectedIds.size - removableSelected.length;
    const message = skipped > 0
      ? `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"}? ${skipped} Builder-linked Part${skipped === 1 ? "" : "s"} will be kept (remove those through the Builder).`
      : `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"} from this Product?`;
    if (!window.confirm(message)) return;
    setBulkRemoving(true);
    const failures = [];
    try {
      for (const part of removableSelected) {
        try {
          await removeManualProductPart(part.id, { builderProductId, expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "remove failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be removed:\n${failures.join("\n")}\n\nThe Product was refreshed. If a removal had already started, use Resume Part Remove to safely continue it.`);
      }
    } finally {
      setBulkRemoving(false);
    }
  };

  const detachableSelected = parts.filter((part) => selectedIds.has(part.id) && part.builder_sync_state === "linked");

  const bulkDetachSelected = async () => {
    if (!builderProductId || bulkDetaching || !detachableSelected.length) return;
    if (!window.confirm(`Detach ${detachableSelected.length} Builder-linked Part${detachableSelected.length === 1 ? "" : "s"} for independent override? Frozen pricing is retained; each Part stops syncing with the Builder.`)) return;
    setBulkDetaching(true);
    const failures = [];
    try {
      for (const part of detachableSelected) {
        try {
          await detachBuilderPartOverride(part.id, undefined, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "detach failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be detached:\n${failures.join("\n")}\n\nThe Product was refreshed. If a detach had already started, use Resume Part Detach to safely continue it.`);
      }
    } finally {
      setBulkDetaching(false);
    }
  };

  const createGroup = async (groupName) => {
    const selectedParts = parts.filter((part) => selectedIds.has(part.id));
    if (!builderProductId || selectedParts.length < 2 || groupCreateRef.current) return;
    groupCreateRef.current = true;
    try {
      await createPartGroupInProduct({
        builderProductId,
        partIds: selectedParts.map((part) => part.id),
        groupName,
        expectedEstimateUpdatedAt,
        expectedPartVersions: Object.fromEntries(selectedParts.map((part) => [part.id, part.updated_date || ""])),
      });
      setGroupModalOpen(false);
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
    } catch (error) {
      setRefreshNonce((value) => value + 1);
      await Promise.resolve(onProductRefresh?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be created."}\n\nThe Product was refreshed. If creation had already started, use Resume Group Create to safely continue it.`);
    } finally {
      groupCreateRef.current = false;
    }
  };

  const partQuery = partSearch.trim().toLowerCase();
  const visibleParts = useMemo(() => {
    if (!partQuery) return parts;
    return parts.filter((part) =>
      [part.part_name, part.client_label, part.inventory_item_name, part.part_type, part.part_subtype]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(partQuery))
    );
  }, [parts, partQuery]);

  const grouped = useMemo(() => {
    const byGroup = new Map();
    groups.forEach((group) => byGroup.set(group.id, []));
    const ungrouped = [];
    visibleParts.forEach((part) => {
      if (part.part_group_id && byGroup.has(part.part_group_id)) byGroup.get(part.part_group_id).push(part);
      else ungrouped.push(part);
    });
    return { byGroup, ungrouped };
  }, [visibleParts, groups]);

  if (!builderProductId) {
    return <div className="px-4 py-4 text-[11px] text-gray-400">This legacy Product does not have Builder Parts yet.</div>;
  }
  if (loading) {
    return <div role="status" className="px-4 py-4 text-[11px] text-gray-400">Loading Parts…</div>;
  }
  if (!parts.length) {
    return (
      <div className="px-4 py-5 text-center border-t border-gray-200 bg-gray-50">
        <div className="text-[11px] font-semibold text-gray-600">This Product does not have any Parts yet.</div>
        <div className="text-[10px] text-gray-400 mt-1">Add a Part from Master Inventory now. Builder-generated BOM Parts will also appear here after the Builder is saved; manually added Parts remain independent add-ons.</div>
        {allowAddParts && !readOnly && (
          <div className="mt-3 flex items-center justify-center gap-2">
            <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[30px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
            <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[30px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
            <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
          </div>
        )}
        <MasterPartPickerModal
          open={partPickerOpen}
          onClose={() => setPartPickerOpen(false)}
          onAdd={async (item, quantity) => {
            await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
        <PartLibraryPickerModal
          open={partLibraryOpen}
          estimateId={estimateId}
          builderProductId={builderProductId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          onClose={() => setPartLibraryOpen(false)}
          onAdded={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
      </div>
    );
  }

  let offset = 0;
  const partsFrozenTotal = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const persistGroupOrder = async (nextGroups, previousGroups) => {
    const failures = [];
    for (let i = 0; i < nextGroups.length; i++) {
      const g = nextGroups[i];
      if (Number(g.sort_order) !== i) {
        try {
          // Anchored on the loaded updated_date when it is known — a group
          // that changed in another session reports updated:0 and is counted
          // below instead of silently writing a stale order. The result count
          // is verified; a swallowed .catch(() => null) here used to make the
          // drag order LOOK applied while it silently reverted on reload.
          const result = await staffEntities.BuilderPartGroup.updateMany(
            g.updated_date ? { id: g.id, updated_date: g.updated_date } : { id: g.id },
            { sort_order: i },
          );
          if (!result || result.updated !== 1) {
            failures.push(g.group_name || "Part Group");
          }
        } catch {
          failures.push(g.group_name || "Part Group");
        }
      }
    }
    if (failures.length) {
      // The order must never LOOK persisted when it is not — restore the
      // pre-drag order and re-read the groups so the next attempt starts
      // from server truth.
      if (previousGroups) setGroups(previousGroups);
      setRefreshNonce((value) => value + 1);
      window.alert(`${failures.length} Part Group${failures.length === 1 ? "" : "s"} could not be reordered (${failures.join(", ")}). The saved order was restored — try again.`);
      return false;
    }
    return true;
  };


  return (
    <div className="border-t border-gray-300 bg-[#f6f6f6] px-3 py-3 space-y-2">
      <div className="flex items-center justify-between gap-2 pb-1">
        <div className="flex items-center gap-2 min-w-0">
          <div className="text-[10px] font-bold tracking-widest text-gray-500 whitespace-nowrap">PRODUCT PARTS · {partQuery ? `${visibleParts.length}/${parts.length}` : parts.length}</div>
          {parts.length > 10 && (
            <div className="relative">
              <Search className="w-3 h-3 text-gray-400 absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none" aria-hidden="true" />
              <input
                value={partSearch}
                onChange={(event) => setPartSearch(event.target.value)}
                placeholder="Search parts…"
                aria-label="Search parts in this product"
                className="h-[26px] w-[150px] pl-6 pr-1.5 border border-gray-300 rounded bg-white text-[11px] focus:outline-none focus:border-lime-400"
              />
            </div>
          )}
        </div>
        {selectionMode ? (
          <div className="flex items-center gap-2">
            <span className="text-[10px] text-gray-500">{selectedIds.size} selected</span>
            <button
              type="button"
              onClick={cancelSelection}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600 hover:bg-gray-50"
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={selectedIds.size < 2}
              onClick={() => setGroupModalOpen(true)}
              className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-40"
            >
              Group Selected Parts
            </button>
            <button
              type="button"
              disabled={bulkDetaching || detachableSelected.length === 0}
              onClick={bulkDetachSelected}
              title={detachableSelected.length === 0 ? "Only Builder-linked Parts can be detached" : "Detach the selected Builder-linked Parts for independent override"}
              className="h-[28px] px-3 rounded border border-amber-300 bg-white text-[11px] font-bold text-amber-700 hover:bg-amber-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Unlink className="w-3.5 h-3.5" aria-hidden="true" /> {bulkDetaching ? "Detaching…" : `Detach Selected (${detachableSelected.length})`}
            </button>
            <button
              type="button"
              disabled={bulkRemoving || removableSelected.length === 0}
              onClick={bulkRemoveSelected}
              title={removableSelected.length === 0 ? "Only independent (non-Builder) Parts can be removed here" : "Remove the selected independent Parts"}
              className="h-[28px] px-3 rounded border border-red-300 bg-white text-[11px] font-bold text-red-600 hover:bg-red-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Trash2 className="w-3.5 h-3.5" aria-hidden="true" /> {bulkRemoving ? "Removing…" : `Delete Selected (${removableSelected.length})`}
            </button>
          </div>
        ) : (
          <div className="flex items-center gap-2">
            {allowAddParts && !readOnly && (
              <>
                <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
                <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[28px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
                <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
              </>
            )}
            {!readOnly && <button
              type="button"
              onClick={() => setSelectionMode(true)}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1.5"
            >
              <Layers3 className="w-3.5 h-3.5" aria-hidden="true" /> Group Parts
            </button>}
          </div>
        )}
      </div>

      {groups.map((group) => {
        const groupParts = grouped.byGroup.get(group.id) || [];
        if (!groupParts.length) return null;
        const node = (
          <PartGroup
            key={group.id}
            group={group}
            parts={groupParts}
            globalOffset={offset}
            selectionMode={selectionMode}
            selectedIds={selectedIds}
            onSelect={togglePartSelection}
            onChanged={async () => {
              setRefreshNonce((value) => value + 1);
              await onProductRefresh?.();
            }}
            builderProductId={builderProductId}
            onEditBuilder={onEditBuilder}
            estimateId={estimateId}
            expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
            availableProducts={availableProducts}
            readOnly={readOnly}
          />
        );
        offset += groupParts.length;
        return readOnly ? node : (
          <div
            key={group.id}
            draggable
            onDragStart={() => setDragGroupIdx(groups.indexOf(group))}
            onDragOver={(e) => { e.preventDefault(); setDragOverIdx(groups.indexOf(group)); }}
            onDragLeave={() => setDragOverIdx(null)}
            onDrop={async (e) => {
              e.preventDefault();
              if (dragGroupIdx === null) return;
              const target = groups.indexOf(group);
              const next = [...groups];
              const [moved] = next.splice(dragGroupIdx, 1);
              next.splice(target, 0, moved);
              setGroups(next);
              setDragGroupIdx(null);
              setDragOverIdx(null);
              const persisted = await persistGroupOrder(next, groups);
              // persistGroupOrder re-reads + reverts on failure itself; on
              // success re-read so the rendered order reflects stored truth.
              if (persisted) setRefreshNonce((v) => v + 1);
            }}
            onDragEnd={() => { setDragGroupIdx(null); setDragOverIdx(null); }}
            className={`${dragOverIdx === groups.indexOf(group) ? "ring-2 ring-emerald-400 rounded" : ""}`}
          >
            {node}
          </div>
        );
      })}
      {grouped.ungrouped.slice(0, partQuery ? grouped.ungrouped.length : ungroupedVisible).map((part, index) => (
        <PartRow
          key={part.id}
          part={part}
          index={offset + index}
          selectionMode={selectionMode}
          selected={selectedIds.has(part.id)}
          onSelect={togglePartSelection}
          onChanged={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
          onEditBuilder={onEditBuilder}
          estimateId={estimateId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          readOnly={readOnly}
        />
      ))}
      {!partQuery && grouped.ungrouped.length > ungroupedVisible && (
        <button
          type="button"
          onClick={() => setUngroupedVisible((value) => value + PART_ROW_PAGE)}
          className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
        >
          Show {Math.min(PART_ROW_PAGE, grouped.ungrouped.length - ungroupedVisible)} more parts ({grouped.ungrouped.length - ungroupedVisible} remaining)
        </button>
      )}
      {partQuery && !visibleParts.length && (
        <div className="py-4 text-center text-[11px] text-gray-400">No Parts match "{partSearch}".</div>
      )}

      <div className="flex items-center justify-between gap-2 pt-2 border-t border-gray-200">
        <div className="text-[10px] font-bold tracking-widest text-gray-500">PARTS TOTAL</div>
        <div className="text-[11px] font-bold text-gray-800">{money(partsFrozenTotal)}</div>
      </div>

      <CreatePartGroupModal
        open={groupModalOpen}
        selectedCount={selectedIds.size}
        onClose={() => setGroupModalOpen(false)}
        onCreate={createGroup}
      />
      <MasterPartPickerModal
        open={partPickerOpen}
        onClose={() => setPartPickerOpen(false)}
        onAdd={async (item, quantity) => {
          await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
      <PartLibraryPickerModal
        open={partLibraryOpen}
        estimateId={estimateId}
        builderProductId={builderProductId}
        expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
        onClose={() => setPartLibraryOpen(false)}
        onAdded={async () => {
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
    </div>
  );
}

import { base44 } from "@/api/base44Client";
import { getModule } from "./moduleRegistry";
import { sourceProjectTotal } from "./builder/builderService";
import { liveCustomerUnitPrice, sourceProjectEconomics } from "./customerPricing";

// Re-reads source sub-estimates for compatibility. Builder-backed Products have
// already been reconciled by ensureEstimateBuilderProducts(), which is the single
// authoritative Product/Part pricing path; do not overwrite those live snapshots
// here with a second, less-complete calculation.
export async function refreshSectionSnapshots(lineItems) {
  const lines = lineItems || [];
  const refreshed = await Promise.all(
    lines.map(async (line) => {
      const mod = getModule(line.module_key);
      if (!mod || !line.project_id) return line;

      const record = await base44.entities[mod.entity].get(line.project_id).catch(() => null);
      if (!record) return line;

      if (line.builder_product_id) {
        return {
          ...line,
          project_name: record.project_name || line.project_name,
          updated_date_snapshot: record.updated_date,
        };
      }

      const sourceTotal = sourceProjectTotal(line, record);
      const frozenTotal = Number(line.total_snapshot || 0);
      const keepLegacyState = line.price_state === "legacy_frozen";
      const economics = keepLegacyState
        ? { internalCost: sourceTotal, customerPrice: liveCustomerUnitPrice(line) }
        : sourceProjectEconomics(line.module_key, record, sourceTotal);
      const liveTotal = economics.internalCost;
      const changed = Math.abs(liveTotal - frozenTotal) > 0.005;
      const hasDetachedParts = Number(line.detached_part_count || 0) > 0 || line.needs_reattach_review;

      return {
        ...line,
        project_name: record.project_name || line.project_name,
        live_total_snapshot: liveTotal,
        live_customer_price_snapshot: economics.customerPrice,
        price_state: hasDetachedParts
          ? "detached_parts"
          : keepLegacyState
            ? "legacy_frozen"
            : changed
              ? "changed"
              : "current",
        last_price_check_at: new Date().toISOString(),
        updated_date_snapshot: record.updated_date,
      };
    })
  );
  return refreshed;
}

// Mirrors the canonical not-found detection in builderEntityPersistence
// (isEntityNotFoundError): a genuinely-missing record is "already gone" while
// every other fetch failure stays an error so a caller never reports a
// section removed when it was not.
const isNotFound = (e) => {
  const status = Number(e?.status || e?.response?.status || e?.response?.statusCode || e?.data?.status || 0);
  if (status === 404) return true;
  const message = [
    e?.message,
    e?.response?.data?.message,
    e?.response?.data?.error,
    e?.data?.message,
    e?.data?.error,
  ].map((v) => String(v || "").toLowerCase()).join(" ");
  return message.includes("not found") || message.includes("does not exist");
};

// Owned sections are created by the estimate, so removing one removes its
// record. (O-014u note: this export had no callers at HEAD 37d401b5a and was
// a latent swallowed-delete defect — fixed rather than removed so the
// documented API stays available but can never fail silently.)
// Returns true when the record is deleted or already gone, false when the
// line is not an owned section (nothing to delete). Transient delete errors
// rethrow so the caller can surface or retry them.
export async function deleteOwnedSection(line) {
  const mod = getModule(line?.module_key);
  if (!line?.owned || !mod || !line.project_id) return false;
  try {
    await base44.entities[mod.entity].delete(line.project_id);
  } catch (e) {
    if (isNotFound(e)) return true;
    throw e;
  }
  return true;
}

// Painting pricing-availability layer.
//
// Wraps calculatePaintingProject with strict finite-number input validation so
// a missing, malformed, or unusable pricing input can no longer silently
// become $0, a hidden default, or a dropped item edge. Mirrors the landed
// Foundation/Vinyl hardening convention:
//   - strict parsers (paintStrictNumber / paintSettingNumber / paintThicknessNumber,
//     owned by paintCalc so the calculator and the scanner resolve identically)
//   - structured issue records { kind, index, itemIndex, field, code, message, hold }
//   - Painting has no catalog entities — the shared Settings rows are the
//     priced surface, so settings issues are kind "paint_catalog" and hold the
//     whole project calc; authored item/project-field issues hold the affected
//     item's derived numbers and every aggregate those numbers feed.
//   - explicit 0 stays valid where the calculator treats it as a real
//     free/zero amount (rates, multipliers, hours, floors, costs); 0 is
//     invalid where the math divides or needs a real magnitude (coverage, the
//     paint mix ratio, the waste multiplier, the labor rate divisor, the
//     letter perimeter factor).
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as PaintingEstimator has always passed them.
//
// Valid inputs take the exact same code path as before: the calc object the
// page receives for a clean project is bit-identical to today's result (plus
// __held / pricingUnavailable / issues metadata flags).

import {
  calculatePaintingProject,
  paintSettingRecorded,
  paintStrictNumber,
  paintThicknessNumber,
} from "./paintCalc";

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- settings scan ----------
// Every Settings row the calculator prices from. [key, human, positive]
// positive: true  → recorded value must be > 0
// positive: false → recorded value must be finite and >= 0
const PRICED_SETTINGS = [
  ["default_labor_rate", "default labor rate ($/hr)", true],
  ["min_labor_hours", "minimum labor hours floor", false],
  ["min_paint_cost", "minimum paint cost floor", false],
  ["default_paint_supplies_per_sqft", "default paint supplies per sq ft", false],
  ["paint_cost_per_unit", "paint cost per unit", false],
  ["hardener_cost_per_unit", "hardener cost per unit", false],
  ["reducer_cost_per_unit", "reducer cost per unit", false],
  ["paint_mix_ratio", "paint mix ratio", true],
  ["hardener_mix_ratio", "hardener mix ratio", false],
  ["reducer_mix_ratio", "reducer mix ratio", false],
  ["mixed_paint_coverage_sqft_per_gallon", "mixed paint coverage (sq ft/gallon)", true],
  ["paint_waste_multiplier", "paint waste multiplier", true],
  ["fixed_paint_waste_gallons", "fixed paint waste (gallons)", false],
  ["paint_mask_rate_per_sqft", "paint mask material rate per sq ft", false],
  ["paint_mask_machine_cutting_rate_per_sqft", "paint mask machine cutting rate per sq ft", false],
  ["paint_mask_application_labor_rate_per_sqft", "paint mask application labor rate per sq ft", false],
  ["paint_mask_cutting_labor_rate_per_sqft", "paint mask cutting labor rate per sq ft", false],
  ["base_labor_hours_per_sqft", "base labor hours per sq ft", false],
  ["setup_time_labor_hours", "setup time (hours)", false],
  ["paint_mixing_labor_hours", "paint mixing labor hours per mix", false],
  ["color_change_setup_hours", "color change setup hours", false],
  ["paint_gun_cleaning_hours", "paint gun cleaning hours", false],
  ["one_side_paint_multiplier", "one-side paint multiplier", false],
  ["both_sides_paint_multiplier", "both-sides paint multiplier", false],
  ["additional_color_multiplier", "additional color multiplier", false],
  ["simple_complexity_multiplier", "simple complexity multiplier", false],
  ["moderate_complexity_multiplier", "moderate complexity multiplier", false],
  ["complex_complexity_multiplier", "complex complexity multiplier", false],
  ["letter_perimeter_factor", "letter perimeter factor", true],
];

const PAINT_UNITS = ["oz", "pint", "quart", "liter", "gallon"];
const TIER_SETTINGS = [
  ["panel_labor_tiers", "panel labor tiers"],
  ["complex_shapes_labor_tiers", "complex shape labor tiers"],
  ["lettering_labor_tiers", "lettering labor tiers"],
];

// Settings rows the calc prices from. Only recorded values can be broken —
// an absent row falls back to the documented module default by design, so it
// is never an issue. Every settings issue holds the whole project calc.
export function paintSettingIssues(settings = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint_catalog", { field, code, message, hold: "project" }));

  for (const [key, human, positive] of PRICED_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const n = paintStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, "paint_setting_unavailable",
        `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in Painting Settings — the stored value cannot price this estimate`);
    }
  }

  // Liquid unit selectors — a recorded-but-unsupported unit resolves 0 in
  // costPerGallon (silently free); a missing unit next to a priced component
  // does the same.
  for (const [costKey, unitKey, human] of [
    ["paint_cost_per_unit", "paint_unit", "paint"],
    ["hardener_cost_per_unit", "hardener_unit", "hardener"],
    ["reducer_cost_per_unit", "reducer_unit", "reducer"],
  ]) {
    const unitRecorded = paintSettingRecorded(settings, unitKey);
    const unitValid = PAINT_UNITS.includes(settings?.[unitKey]);
    if (unitRecorded && !unitValid) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: select a supported ${human} unit (oz / pint / quart / liter / gallon) in Painting Settings`);
    } else if (!unitValid && (paintStrictNumber(settings?.[costKey]) ?? 0) > 0) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: set a ${human} unit — a recorded ${costKey} prices as $0 without one`);
    }
  }

  // Labor tier tables are JSON arrays of {min_quantity, max_quantity,
  // labor_multiplier}. Malformed JSON silently disables the whole table;
  // malformed row fields silently dead-window the tier or reprice it.
  for (const [key, human] of TIER_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const raw = settings[key];
    let tiers = raw;
    if (!Array.isArray(tiers)) {
      try {
        const parsed = JSON.parse(raw || "[]");
        tiers = Array.isArray(parsed) ? parsed : null;
      } catch {
        tiers = null;
      }
    }
    if (tiers === null) {
      add(key, "paint_labor_tiers_unavailable",
        `Setting ${key}: the ${human} table is not a valid JSON array — repair it in Painting Settings or quantity discounts price as 1x`);
      continue;
    }
    tiers.forEach((row, rowIdx) => {
      const where = `Setting ${key} row ${rowIdx + 1}`;
      for (const [field, human2] of [["min_quantity", "minimum quantity"], ["max_quantity", "maximum quantity"]]) {
        if (row?.[field] !== undefined && row?.[field] !== null
          && (paintStrictNumber(row[field]) === null || paintStrictNumber(row[field]) < 0)) {
          add(key, "paint_labor_tier_row_unavailable",
            `${where}: record a finite, nonnegative ${human2} — the stored value dead-windows this tier`);
        }
      }
      if (row?.labor_multiplier !== undefined && row?.labor_multiplier !== null
        && (paintStrictNumber(row.labor_multiplier) === null || paintStrictNumber(row.labor_multiplier) < 0)) {
        add(key, "paint_labor_tier_row_unavailable",
          `${where}: record a finite, nonnegative labor multiplier — the stored value cannot price this tier`);
      }
    });
  }

  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each paint item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
const LETTER_SIZES = ["extra_small", "small", "normal", "medium", "large", "extra_large"];
const PRESENT = (v) => v !== undefined && v !== null;
// For this module a cleared stored value is malformed input, not an absent
// one: paintCalc's num("") launders to 0 / a clamp to 1 silently.
const nonnegField = (v) => paintStrictNumber(v) !== null && paintStrictNumber(v) >= 0;

export function paintItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("paint", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — every geometry branch keys on it; anything else prices a
  // silent $0 item.
  if (PRESENT(rawItem?.item_type) && !["panel", "lettering", "complex_shapes"].includes(rawItem.item_type)) {
    add("item_type", "paint_item_type_unavailable",
      "select Panel, Lettering, or Complex Shape — the stored type prices as $0 silently");
  }
  const effectiveType = rawItem?.item_type || "panel";

  // thickness — the strict imperial parse: malformed text used to vanish into
  // 0 (edge area silently dropped; "-1" even laundered to +1). Panel math has
  // an explicit edge-less branch so a real 0 is tolerated there; lettering
  // and complex shapes price nothing at all without a positive thickness.
  if (rawItem?.thickness !== undefined) {
    const t = paintThicknessNumber(rawItem.thickness);
    if (t === null || t < 0) {
      add("thickness", "paint_thickness_unavailable",
        "record a usable thickness (inches, e.g. 1/2 or 1-1/4) — the stored value silently drops edge pricing");
    } else if (t === 0 && effectiveType !== "panel") {
      add("thickness", "paint_thickness_unavailable",
        "record a positive thickness — lettering and complex shapes price nothing at 0\"");
    }
  }

  // length / width — every branch gates > 0; blank, zero, negative or
  // malformed dimensions silently collapse the item's paint and labor.
  for (const field of ["length", "width"]) {
    const n = paintStrictNumber(rawItem?.[field]);
    if (n === null || n <= 0) {
      add(field, "paint_dimension_unavailable",
        `record a positive, finite ${field === "length" ? (effectiveType === "lettering" ? "letter count" : "length") : (effectiveType === "lettering" ? "letter height" : "width")} (inches) — a blank or zero dimension prices the item as $0 silently`);
    }
  }

  // quantity — lettering forces 1 by design; other types clamp <1 to 1 in the
  // math, so a recorded 0/blank/malformed value silently repriced as one.
  if (effectiveType !== "lettering" && PRESENT(rawItem?.quantity)) {
    const q = paintStrictNumber(rawItem.quantity);
    if (q === null || q < 1) {
      add("quantity", "paint_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value prices as 1 silently");
    }
  }

  // paint_sides — the stored value chooses the multiplier branch; "none" is a
  // tolerated legacy alias for one_side.
  if (PRESENT(rawItem?.paint_sides) && rawItem.paint_sides !== ""
    && !["one_side", "both_sides", "none"].includes(rawItem.paint_sides)) {
    add("paint_sides", "paint_sides_unavailable",
      "choose One side or Both sides — the stored value silently prices as one side");
  }

  // edge complexity — complex-shape edge multiplier; negative values priced
  // negative edge area, malformed text repriced as 1x, blank as 0 edges.
  if (effectiveType === "complex_shapes" && PRESENT(rawItem?.edge_complexity_multiplier)
    && !nonnegField(rawItem.edge_complexity_multiplier)) {
    add("edge_complexity_multiplier", "paint_edge_complexity_unavailable",
      "record a finite, nonnegative edge complexity multiplier — the stored value cannot price edges");
  }

  // paint mask sq ft — consumed when more than one color is selected; blank
  // or malformed text silently priced as no mask.
  if (PRESENT(rawItem?.paint_mask_sqft) && !nonnegField(rawItem.paint_mask_sqft)) {
    add("paint_mask_sqft", "paint_mask_sqft_unavailable",
      "record a finite, nonnegative paint mask area (sq ft) — the stored value drops mask pricing");
  }

  // fixed waste gallons / base supplies — recorded junk silently became 0.
  for (const [field, human] of [["fixed_waste_gallons", "fixed waste (gallons)"], ["base_supplies_cost", "base supplies cost ($)"]]) {
    if (PRESENT(rawItem?.[field]) && !nonnegField(rawItem[field])) {
      add(field, field === "fixed_waste_gallons" ? "paint_fixed_waste_unavailable" : "paint_base_supplies_unavailable",
        `record a finite, nonnegative ${human} — the stored value silently became $0`);
    }
  }

  // letter_size — drives the complexity class for lettering only.
  if (effectiveType === "lettering" && PRESENT(rawItem?.letter_size) && rawItem.letter_size !== ""
    && !LETTER_SIZES.includes(rawItem.letter_size)) {
    add("letter_size", "paint_letter_size_unavailable",
      "the stored letter size is unsupported — it silently prices as moderate complexity");
  }

  // paint_colors — the math reads the array length verbatim (ported); a
  // non-array value normalized to [] silently bills no paint.
  if (PRESENT(rawItem?.paint_colors) && !Array.isArray(rawItem.paint_colors)) {
    add("paint_colors", "paint_colors_unavailable",
      "the stored color list is malformed — it silently bills $0 paint; re-add the colors");
  }

  return issues;
}

// ---------- project-level scan ----------
export function paintProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint", { field, code, message, hold: "project" }));

  // items must be an array — the calc maps it verbatim.
  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "paint_items_unavailable",
      "the stored paint items are malformed — the project cannot be repriced");
  }

  // paint_supplies_per_sqft — blank/null laundered to $0 under num(); a
  // malformed string silently became the settings default. Explicit 0 stays a
  // legitimate free supplies rate.
  if (project?.paint_supplies_per_sqft !== undefined
    && (paintStrictNumber(project.paint_supplies_per_sqft) === null
      || paintStrictNumber(project.paint_supplies_per_sqft) < 0)) {
    add("paint_supplies_per_sqft", "paint_supplies_rate_unavailable",
      "record a finite, nonnegative supplies rate per sq ft — a blank or malformed value silently repriced supplies");
  }

  return issues;
}

// ---------- calc wrapper ----------
// Returns { calc, issues, held }. The calc keeps the real result shape; when
// held, every derived number a flagged input could have tainted is null —
// saved acknowledged totals on the record are the display fallback, never an
// invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["supplies_cost", "paint_cost", "paint_gallons", "labor_hours", "labor_cost", "paintable_sqft"];

export function calcPaintingProject(project = {}, settings = {}) {
  const issues = [
    ...paintSettingIssues(settings),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => paintItemIssues(item, index))),
    ...paintProjectInputIssues(project),
  ];

  // A non-array items value is itself a project-level hold; hand the calc an
  // empty list so it still returns a real result shape (the input object is
  // never mutated — totals are nulled below regardless).
  const calcable = Array.isArray(project?.items) ? project : { ...project, items: [] };
  const calc = calculatePaintingProject(calcable, settings);
  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held };
  }

  const out = { ...calc, totals: { ...calc.totals } };
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  // Held items keep their raw row but lose every derived number — the totals
  // sum those numbers so every aggregate is untrustworthy too.
  out.items = calc.items.map((item, index) => {
    if (!hasProjectHold && !itemHolds.has(index)) return item;
    const heldItem = { ...item };
    for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
    return heldItem;
  });
  for (const field of Object.keys(out.totals)) out.totals[field] = null;
  if (hasProjectHold) out.liquidPaintRate = null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held };
}

// ---------- UI helpers ----------
// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasPaintCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields: "" stays "" so the input
// does not fight the user mid-typing; parseable text becomes a number;
// anything else stays raw so validation can flag it instead of laundering it
// into 0 (paintCalc's num("") silently read as 0 before).
export const paintDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

