              className="mt-2 rounded-sm border border-amber-400 bg-white px-2 py-1 text-[12px] font-semibold text-amber-800 disabled:opacity-50">
              {catalogReloading ? "Reloading catalogs…" : "Reload catalogs"}
            </button>
          </div>
        )}

